SELECT * FROM ( SELECT T.STORE_ID as storeId, T.ACTIVITY_ID as activityId, T.AWARD_ID as awardId, T.AWARD_NUM as awardNum, T.AWARD_PWD as awardPwd, T.AWARD_STATE as awardState, T.CREATED_DATE as createdDate, T.CREATED_USER as createdUser, T.UPDATED_DATE as updatedDate, T.UPDATED_USER as updatedUser, T.VERSION as version FROM CMWA_WX_ACT_AWARD_STORE T WHERE 1=1
AND T.ACTIVITY_ID = #{param.activityId,jdbcType=VARCHAR}
AND T.AWARD_ID = #{param.awardId,jdbcType=VARCHAR}
AND T.AWARD_STATE = #{param.awardState,jdbcType=VARCHAR}
AND T.VERSION = #{param.version,jdbcType=NUMERIC}
ORDER BY DBMS_RANDOM.VALUE
) WHERE 1=1
AND rownum = 1

